import React, { forwardRef, useEffect } from 'react';
import styled from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { PanelContext } from './contexts/PanelContext.js';
import { _useConditionalPagePanel } from './hooks/_useConditionalPagePanel.js';
import { _usePageContext } from './hooks/_usePageContext.js';
import {
  PREFERRED_WIDTHS,
  PANEL_ORDER,
  MIN_WIDTHS,
  BREAKPOINTS,
} from './Page.js';
import type { PanelProps } from './Panel/Panel.js';
import { Panel } from './Panel/Panel.js';
import { Resizer } from './Panel/Resizer.js';
import type { PanelSize } from './Panel/types/shared-panel-types.js';
import type {
  PagePanelSizes,
  PagePanelProps,
} from './types/shared-page-types.js';
import { useBreakpoint } from '../../core/hooks/useBreakpoint.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import {
  DrawerProps,
  _Drawer as Drawer,
} from '../../overlays/_drawer/_Drawer.js';

//#region Styled Components
const StyledDetailView = /* @__PURE__ */ styled(Panel)<PanelProps>({
  backgroundColor: Colors.Background.Base.Default,
  borderRadius: `${Borders.Radius.Surface.Default} 0 0 0`,
  height: '100%',
  overflow: 'hidden',
  transition: `border-radius ${Animations.FadeIn.Duration.Fast} ${Animations.FadeIn.Easing}`,

  '@media(prefers-reduced-motion)': {
    transition: '',
  },
});
StyledDetailView.displayName = 'Page.DetailView';

const StyledPageDrawer = /* @__PURE__ */ styled(Drawer)<DrawerProps>({
  padding: Spacings.Size8,
  boxSizing: 'border-box',
});
StyledPageDrawer.displayName = 'Page.DetailViewDrawer';

export const PageDrawer = (props: DrawerProps) => {
  return <StyledPageDrawer {...props} />;
};
//#endregion

//#region Props
export interface DetailViewOwnProps
  extends WithChildren,
    Omit<React.HTMLAttributes<HTMLDivElement>, 'onResize' | keyof StylingProps>,
    StylingProps,
    DataTestId {
  /**
   * The disired width of the detail view.
   * Depending on the available screen width and other panel configurations,
   * the size of the panel might not match the `preferredWidth` exactly.
   * @defaultValue 25%
   */
  preferredWidth?: PanelSize;
  /**
   * The minimum width of the detail view in pixels.
   * @defaultValue 320
   */
  minWidth?: number;
  /**
   * Screen size below which the overlay Drawer will be shown.
   * @defaultValue 1280
   */
  breakpoint?: number;
  /**
   * If the detail views width can be resized (by drag and drop)
   * @defaultValue true
   */
  resizable?: boolean;
  /**
   * Callback triggered after resizing is finished with the new panel sizes of
   * all existing panels and the newly applied panel width (in px).
   */
  onResize?: (sizes: PagePanelSizes, width: number) => void;
  /**
   * Notifies the user if an action happened that should change the dismissed state
   * like clicking on the backdrop on mobile.
   * The returned state is only a recommendation and might differ from what the actual
   * state of the panel should be.
   */
  onDismissChange?: (state: boolean, reason: string) => void;
}

export type DetailViewProps = DetailViewOwnProps & PagePanelProps;

//#endregion

/** The `DetailView` component is used inside the `Page` component for displaying content in the corresponding panel. */
export const DetailView = forwardRef<HTMLDivElement, DetailViewProps>(
  (props, forwardedRef) => {
    const {
      children,
      dismissed,
      defaultDismissed,
      onDismissChange,
      preferredWidth = PREFERRED_WIDTHS.details,
      minWidth = MIN_WIDTHS.details,
      breakpoint = BREAKPOINTS.details,
      resizable = true,
      onResize,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: DetailViewProps = props;

    const showPanel = useBreakpoint(`(min-width: ${breakpoint}px)`, false);

    // Register the panel with the page and set its initial state.
    _useConditionalPagePanel({
      name: 'details',
      defaultDismissed,
      dismissed,
      showPanel,
      breakpoint,
    });
    const { detailsDismissed, setPanelDismissed } = _usePageContext();
    const isControlled = dismissed !== undefined;

    useEffect(() => {
      const reason = showPanel ? 'above breakpoint' : 'below breakpoint';
      onDismissChange?.(!showPanel, reason);
      // Excluding onDismissChange to trigger the effect only if the screen size reaches the breakpoint.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [showPanel]);

    // The drawer handels the dismissing on its own, to ensure the proper animation, therefore, the check excludes the mobile view.
    // If the panel is controlled, we check the dismissed prop directly to make sure the panel is instantly added to the state when
    // mounting. Since the default state of the panel in the context is set to 'dismissed', the layout effect in the parent panel would
    // else be triggered twice. Initially, only with the 'main' panel, and then again to add the 'sidebar'.
    if (
      ((isControlled && dismissed) || (!isControlled && detailsDismissed)) &&
      showPanel
    ) {
      return null;
    }

    return (
      <PanelContext.Provider value={{ panelName: 'details' }}>
        {showPanel ? (
          <>
            <Resizer
              data-testid="page-details-resize-handle"
              order={PANEL_ORDER.details}
              resizable={resizable}
              name="details-resize-handle"
            />
            <StyledDetailView
              {...remainingProps}
              onResize={(sizes, width) => {
                onResize?.(sizes as PagePanelSizes, width);
              }}
              ref={forwardedRef}
              name="details"
              order={PANEL_ORDER.details}
              preferredWidth={preferredWidth}
              minWidth={minWidth}
              resizable={resizable}
              dismissible="right"
              className={consumerClassName}
              style={consumerStyle}
              data-testid={dataTestId}
            >
              {children}
            </StyledDetailView>
          </>
        ) : (
          <PageDrawer
            placement="right"
            width="wide"
            isDismissed={detailsDismissed}
            onDismiss={(state, reason) => {
              // Close panel if it is uncontrolled and the user clicks on the backdrop.
              if (
                dismissed === undefined &&
                state === true &&
                (reason === 'backdrop' || reason === 'escape')
              ) {
                setPanelDismissed('details', true);
              }
              onDismissChange?.(state, reason);
            }}
            className={consumerClassName}
            style={consumerStyle}
            data-testid={dataTestId}
            {...remainingProps}
          >
            {children}
          </PageDrawer>
        )}
      </PanelContext.Provider>
    );
  },
);

(DetailView as typeof DetailView & { displayName: string }).displayName =
  'Page.DetailView';
